// لایه نیت تجاری «بیمه مسئولیت صنایع». استاتیک، بدون وابستگی به DB.
// قواعد صداقت (YMYL): هیچ رقم حق بیمه، آمار یا ادعای حقوقی اختراعی
// مجاز نیست؛ فقط توصیف کیفی ریسک + لینک به محصول‌های واقعی موجود.
// تاریخ بازبینی: ۱۴۰۵/۰۸/۰۳ (معادل 2026-10-25) — هم‌سو با بقیه صفحات فارسی.

export type IndustryRisk = { title: string; text: string };
export type IndustryCoverage = { label: string; href: string; why: string };
export type IndustryStep = { title: string; description: string };
export type IndustryFaq = { question: string; answer: string };
export type IndustrySource = { title: string; reference: string };

export type Industry = {
  /** اسلاگ مسیر /industry/<slug> */
  slug: string;
  /** نام کوتاه صنعت — برای کارت هاب و بردکرامب */
  name: string;
  /** یک‌خط خلاصه ریسک — برای کارت هاب */
  riskSummary: string;
  /** H1 یگانه صفحه */
  h1: string;
  /** عنوان متا — حداکثر ۶۰ نویسه */
  title: string;
  /** توضیح متا — ۱۴۵ تا ۱۶۰ نویسه */
  description: string;
  /** پاسخ مستقل ۴۰–۶۰ واژه برای AnswerBlock */
  answer: string;
  risks: IndustryRisk[];
  coverages: IndustryCoverage[];
  steps: IndustryStep[];
  faqs: IndustryFaq[];
  sources: IndustrySource[];
  /** تاریخ بازبینی به قالب عددی فارسی */
  lastReviewed: string;
  /** همان تاریخ به ISO برای AuthorBox/faDate */
  lastReviewedIso: string;
};

